export async function closeTestConnections(
  clients: WebSocket[],
  servers: Array<ReturnType<typeof createServer>>
): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

