async function answerFrame(ws: WebSocket, validation: ValidationResult, sessionStore?: SessionStore): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') {
    if (!sessionStore?.listFor) {
      sendJson(ws, {type: 'session_list', sessions: []});
      return;
    }
    try {
      const sessions = await sessionStore.listFor((ws as WebSocket & {userId: string | number}).userId, {
        limit: message.limit,
        before: message.before,
      });
      sendJson(ws, {
        type: 'session_list',
        sessions: sessions.map(({createdAt, updatedAt, ...summary}) => ({
          ...summary,
          createdAt: createdAt.toISOString(),
          updatedAt: updatedAt.toISOString(),
        })),
      });
    } catch (error) {
      log.error('ws', 'conversation list failed', {
        sessionId: (ws as WebSocket & {sessionId?: string}).sessionId,
        userId: (ws as WebSocket & {userId?: string | number}).userId,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
    }
  }
}

