140	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
141	  try {
142	    await action();
143	  } catch (error) {
144	    const message = error instanceof Error ? error.message : 'Unknown error';
145	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
146	    log.error('message', 'handling error', {error: message, code});
147	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
