155	async function handleUserMessage(
156	  ws: WebSocket,
157	  session: ChatSession,
158	  orchestrator: ChatOrchestrator,
159	  content: string,
160	  signal: AbortSignal | undefined
161	): Promise<void> {
162	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
163	
164	  const userEntry = createUserEntry(content);
165	  const userIndex = appendEntry(session, userEntry);
166	  sendUpsert(ws, userIndex, userEntry);
167	
168	  const parser = new ThinkingTagParser();
169	  const state: StreamState = {
170	    thinkingIndex: null,
171	    assistantIndex: null,
172	    suppressOutput: false,
173	    sentAssistantIndices: [],
174	  };
175	
176	  let textChunkCount = 0;
177	
178	  try {
179	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
180	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
181	      if (signal?.aborted) break;
182	      textChunkCount = logChunk(chunk, textChunkCount);
183	      processChunk(ws, session, state, parser, chunk);
184	    }
185	  } finally {
186	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
187	    flushHeldText(ws, session, state, parser);
188	    closeCutOff(ws, session, state, 'thinkingIndex');
189	    closeCutOff(ws, session, state, 'assistantIndex');
190	  }
191	
192	  if (textChunkCount > 0) {
193	    log.debug('stream', `received ${textChunkCount} text chunks`);
194	  }
195	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
196	}
