198	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
199	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
200	  if (chunk.type === 'text') return textChunkCount + 1;
201	
202	  if (textChunkCount > 0) {
203	    log.debug('stream', `received ${textChunkCount} text chunks`);
204	  }
205	
206	  if (chunk.type === 'tool_result') {
207	    log.debug('stream', 'tool_result chunk', {
208	      messageCount: chunk.clientMessages.length,
209	      types: chunk.clientMessages.map(m => m.type),
210	    });
211	    return 0;
212	  }
213	
214	  log.debug('stream', 'chunk', {type: chunk.type});
215	  return 0;
216	}
