218	function processChunk(
219	  ws: WebSocket,
220	  session: ChatSession,
221	  state: StreamState,
222	  parser: ThinkingTagParser,
223	  chunk: MessageChunk
224	): void {
225	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
226	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
227	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
228	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
229	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
230	}
